#!/usr/bin/env bash
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# Deployed-source tests always exercise the portable repository fixture.
# Set SDO_DRIFT_SEED explicitly to also check a full deployed hotel seed.

(
    cd "$root/sdo/operator/runtime"
    go test -run '^(TestPendingDriftJoinsIncidentBeforeVerifiedClosure|TestPendingDriftPreventsVerificationWhenPeerIsUnresolved|TestLearningRepairAtThresholdOneDispatchesFastPathWithoutResponder|TestLearningCreditRequiresSuccessfulOutcomeAndOriginalProgramRevision|TestLearningEvidenceRejectsUnvalidatedSyntheticAndMismatchedCaptures|TestLearningCreditCannotEraseSubsequentFastPathFailure|TestWatchEventProgramMatchesOwnedServiceBeforeSweep|TestWatchEventProgramMatchesUnownedServiceBeforeSweep|TestWatchEventProgramsUseHintOnceForOwnedAndUnownedChanges|TestWatchEventTransientMidRolloutProgramNeverFires|TestWatchEventRepairQueuesNothingAndSweepClearsLearnedIncident|TestWatchEventUnownedChangeWithoutProgramMatchIsQuiet|TestWatchEventPendingBindingsSurviveRestartIndependently|TestProgramSweepUsesDefaultTimedConfirmation|TestHermeticFastloopRealGoGate|TestHermeticFakeConfigMapEnforcesProductionLimit|TestRegisteredReflectionWorkerRejectsOversizedResultBeforeCommit|TestHermeticResponderProgramReuseThroughRealToolTransport|TestHermeticAcceptedSourceAfterMemoryCommit|TestAcceptedSourceRenderFailureIsObjectScoped|TestAcceptedSourceDoesNotReuseImagesAcrossSourceChange|TestControllerAdoptsAvailableObjectsWithExplicitRenderGap|TestGitPlanSourceUsesOnlyDeployedManifestSet|TestGitPlanSourceSelectsDeployedHotelSeed|TestControllerAdoptsSeededServiceThenDispatchesLaterDrift|TestUnexplainedTargetPortOpensLatentIncidentWithDriftCorpus|TestUnexplainedDriftDuringResponseAttachesToOpenIncident|TestHermeticForeignNetworkPolicyOpensLatentIncident|TestHermeticForeignNetworkPolicyInvariantRepeat|TestForeignNetworkPolicyInvariantNearMisses|TestForeignDriftNormalChurn|TestHermeticBenignDriftAcrossFastloopResetAndNextIncident|TestHermeticDriftlive4NewFaultAfterHealthyBaseline|TestRepairedDriftRecursWithoutProgramAfterRestart|TestVerifyRetainsDriftWithHealthyDetectors|TestClosureRetainsDriftWithHealthyDetectors|TestVerifyRetainedLearnedDriftRequiresEveryBinding|TestUnexplainedDriftSourceErrorNeverClears|TestOrdinaryDriftAdmissionBudgetsBatchingAndNewKeyPriority|TestTerminalDriftResponderFailureDoesNotWaitForTTLOrCloseHealthy|TestCheckedBenignNoopClosesWithoutMitigationCredit|TestHermeticFourIncidentTrustedFastPathCompletesWithoutResponderJob|TestHermeticSourceReconcileLearningAndTrustAtThreeSkipsResponder|TestHermeticRoutingCaptureCompilesReplayableMitigator|TestIncidentCaptureRecordsRoutingTCPBeforeAnyProgramExists|TestRoutingCaptureHasCountAndTimeBudgets|TestRunCapturesRoutingWithoutTrafficWorkloads|TestRunStartsRoutingProberWithoutTrafficWorkloads|TestRoutingCaptureRecordsUnavailableCapabilityOnce|TestHermeticTrustedLatentDriftFastPathSkipsResponderAndReflection|TestFailedFastPathRollsBackAndDispatchesResponderWithSummary|TestTrustedProgramFastPathRequiresEveryFindingExplained|TestTrustedProgramFastPathRejectsNeedsJudgement|TestNativeBrokerSkipsReflectionAfterTrustedFastPath)$' -count=1 .
)

cd "$root"
uv run --extra test pytest -q -p no:tach \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_hermetic_run.py \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_composite.py::test_failed_composite_reset_restarts_controller_before_next_incident \
    tests/unit/benchmarks/sregym/adapter/test_native_persistent_ops.py::test_reset_stage_syncs_accepted_pvc_before_recreating_controller \
    tests/unit/benchmarks/sregym/fastloop/test_fastloop_reset.py::test_reset_cancels_and_awaits_workers_before_deleting_captures \
    tests/unit/benchmarks/sregym/adapter/test_scripted_drift.py
